require __DIR__.'/config/bootstrap.php';$path='/'.trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$path=preg_replace('#^/api#','',$path)?:'/';$method=$_SERVER['REQUEST_METHOD'];if(!in_array($method,['GET','OPTIONS'],true)&&!str_starts_with($path,'/auth/login')&&!str_starts_with($path,'/auth/register'))csrf();
