if($path==='/specialties'){$q=db()->query("SELECT s.id,s.name,s.slug,s.description,s.icon,s.color,COUNT(q.id) question_count FROM specialties s LEFT JOIN questions q ON q.specialty_id=s.id AND q.status='published' AND q.deleted_at IS NULL WHERE s.is_active=1 GROUP BY s.id ORDER BY s.display_order");json_response(true,'Data berhasil dimuat',['items'=>$q->fetchAll()]);}
