if(preg_match('#^/quizzes/(\d+)/submit$#',$path,$m)&&$method==='POST'){$u=user();$p=db();$p->beginTransaction();$s=$p->prepare("SELECT * FROM quiz_attempts WHERE id=? AND user_id=? AND status='in_progress' FOR UPDATE");$s->execute([$m[1],$u['id']]);$a=$s->fetch();if(!$a){$p->rollBack();json_response(false,'Kuis sudah dikirim atau tidak ditemukan',null,409);}$c=$p->prepare('SELECT COUNT(*) FROM quiz_answers a JOIN question_options o ON o.id=a.option_id WHERE a.attempt_id=? AND o.is_correct=1');$c->execute([$a['id']]);$correct=(int)$c->fetchColumn();$answeredQuery=$p->prepare('SELECT COUNT(*) FROM quiz_answers WHERE attempt_id=?');$answeredQuery->execute([$a['id']]);$answered=(int)$answeredQuery->fetchColumn();$total=(int)$a['total_questions'];$p->prepare("UPDATE quiz_attempts SET status='submitted',correct_count=?,incorrect_count=?,score=?,submitted_at=NOW(),duration_seconds=TIMESTAMPDIFF(SECOND,started_at,NOW()) WHERE id=?")->execute([$correct,$answered-$correct,$total?round($correct/$total*100):0,$a['id']]);$p->commit();json_response(true,'Kuis berhasil dikirim');}
